type RTDALLoadFailure struct {
	Source string
	Error  string
}

func LoadRTDALPackageWithReport(name string) (*runtime.Context, int, []RTDALLoadFailure) {
	ctx := runtime.NewContext()
	loaded := 0
	failures := []RTDALLoadFailure{}
	for _, unit := range RTDALCorpus {
		if unit.Package != name || !unit.Library {
			continue
		}
		func() {
			defer func() {
				if recovered := recover(); recovered != nil {
					failures = append(failures, RTDALLoadFailure{Source: unit.Source, Error: fmt.Sprint(recovered)})
				}
			}()
			unit.Load(ctx)
			loaded++
		}()
	}
	return ctx, loaded, failures
}

func LoadRTDALPackage(name string) *runtime.Context {
	ctx, _, _ := LoadRTDALPackageWithReport(name)
	return ctx
}
